<?php
declare(strict_types=1);require_once __DIR__.'/includes/layout.php';login_required();$pdo=db();$id=post_int('id')?:filter_var($_GET['id']??0,FILTER_VALIDATE_INT);$r=['employee_username'=>'','employee_firstname'=>'','employee_lastname'=>'','employee_telephone'=>'','employee_email'=>'','department_id'=>'','employee_type'=>'','employee_salary'=>'','employee_hiring_date'=>date('Y-m-d')];if($id){$s=$pdo->prepare('SELECT * FROM employee WHERE employee_id=?');$s->execute([$id]);$r=$s->fetch()?:$r;}$deps=$pdo->query('SELECT * FROM department ORDER BY department_name')->fetchAll();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$u=post('employee_username');$pw=(string)($_POST['employee_password']??'');$fn=post('employee_firstname');$ln=post('employee_lastname');$tel=post('employee_telephone');$email=post('employee_email');$dep=post_int('department_id')?:null;$type=post('employee_type');$salary=(float)($_POST['employee_salary']??0);$date=post('employee_hiring_date');if($id){if($pw!==''){$pdo->prepare('UPDATE employee SET employee_username=?,employee_password=?,employee_firstname=?,employee_lastname=?,employee_telephone=?,employee_email=?,department_id=?,employee_type=?,employee_salary=?,employee_hiring_date=? WHERE employee_id=?')->execute([$u,password_hash($pw,PASSWORD_DEFAULT),$fn,$ln,$tel,$email,$dep,$type,$salary,$date,$id]);}else{$pdo->prepare('UPDATE employee SET employee_username=?,employee_firstname=?,employee_lastname=?,employee_telephone=?,employee_email=?,department_id=?,employee_type=?,employee_salary=?,employee_hiring_date=? WHERE employee_id=?')->execute([$u,$fn,$ln,$tel,$email,$dep,$type,$salary,$date,$id]);}}else{$pdo->prepare('INSERT INTO employee(employee_username,employee_password,employee_firstname,employee_lastname,employee_telephone,employee_email,department_id,employee_type,employee_salary,employee_hiring_date) VALUES(?,?,?,?,?,?,?,?,?,?)')->execute([$u,password_hash($pw?:'admin123',PASSWORD_DEFAULT),$fn,$ln,$tel,$email,$dep,$type,$salary,$date]);}flash('success','Employee saved.');redirect('employees.php');}
page_header($id?'Edit Employee':'Add Employee','employee');?>
<div class="page-head"><h1><?=$id?'Edit':'Add'?> Employee</h1><a class="btn" href="employees.php">Back</a></div><form class="card form-grid" method="post"><?=csrf_field()?><input type="hidden" name="id" value="<?=$id?>"><label>Username<input name="employee_username" value="<?=e($r['employee_username'])?>" required></label><label>Password<input type="password" name="employee_password" <?=$id?'placeholder="Leave blank to keep current"':'required'?>></label><label>First name<input name="employee_firstname" value="<?=e($r['employee_firstname'])?>" required></label><label>Last name<input name="employee_lastname" value="<?=e($r['employee_lastname'])?>" required></label><label>Telephone<input name="employee_telephone" value="<?=e($r['employee_telephone'])?>"></label><label>Email<input type="email" name="employee_email" value="<?=e($r['employee_email'])?>" required></label><label>Department<select name="department_id"><option value="">None</option><?php foreach($deps as $d):?><option value="<?=$d['department_id']?>" <?=$r['department_id']==$d['department_id']?'selected':''?>><?=e($d['department_name'])?></option><?php endforeach;?></select></label><label>Employee Type<input name="employee_type" value="<?=e($r['employee_type'])?>"></label><label>Salary<input type="number" step="0.01" name="employee_salary" value="<?=e($r['employee_salary'])?>"></label><label>Hiring Date<input type="date" name="employee_hiring_date" value="<?=e($r['employee_hiring_date'])?>"></label><div class="full"><button class="btn primary">Save Employee</button></div></form><?php page_footer();?>
